<?php $pageTitle='Notes & PDFs';require_once __DIR__.'/functions.php';$resources=db()->query("SELECT * FROM resources ORDER BY id DESC")->fetchAll();include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Notes & PDFs</h1><p class="muted">All files uploaded from Admin appear here automatically.</p></div></section><section class="section" style="padding-top:10px"><div class="container list"><?php if(!$resources):?><div class="panel"><h3>No resources yet.</h3></div><?php endif;?><?php foreach($resources as $r):?><div class="resource"><div><div class="meta"><span><?=e($r['category'])?></span><span><?=e($r['type'])?></span></div><h3><?=e($r['title'])?></h3><p class="muted"><?=e($r['description'])?></p><small class="muted"><?=e($r['original_name'])?></small></div><div class="btns"><a class="secondary" href="<?=e($r['file_path'])?>" target="_blank">View</a><a class="primary" href="<?=e($r['file_path'])?>" download>Download</a></div></div><?php endforeach;?></div></section><?php include 'includes/footer.php';?>
